import{_ as t,c as r,o as a,ae as i}from"./chunks/framework.BtEkjhVd.js";const m=JSON.parse('{"title":"Architecture Decision Record 2: Use React JS for Web Development Framework","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr-choose-web-framework/adr2.md","filePath":"architecture/adr-choose-web-framework/adr2.md"}'),o={name:"architecture/adr-choose-web-framework/adr2.md"};function n(s,e,c,d,l,h){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="architecture-decision-record-2-use-react-js-for-web-development-framework" tabindex="-1">Architecture Decision Record 2: Use React JS for Web Development Framework <a class="header-anchor" href="#architecture-decision-record-2-use-react-js-for-web-development-framework" aria-label="Permalink to &quot;Architecture Decision Record 2: Use React JS for Web Development Framework&quot;">​</a></h1><p>Date: 09/09/2024</p><h1 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h1><p>We are building the fAIr platform that requires high performance, fast development cycles, and scalability. The development team is proficient in React and Next.js, and HOT has a history of using React.js for most of its projects. To maintain consistency and leverage existing knowledge, we are considering web development frameworks that align with our team&#39;s skill set and project requirements.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li>Speed of development: minimizing the time required to build and deploy features.</li><li>Performance: ensuring the web application is highly performant, especially in terms of loading times and SEO.</li><li>Familiarity with the framework: developers are experienced with React and Next.js, reducing the need for additional training.</li><li>Ease of deployment: Avoid vendor lock-in during deployment.</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><p><a href="https://react.dev/" target="_blank" rel="noreferrer">React.js</a>: Familiarity with the team, widely used in the company, rich ecosystem of libraries.</p></li><li><p><a href="https://nextjs.org/" target="_blank" rel="noreferrer">Next.js</a>: Built on top of React, offers server-side rendering and static site generation out of the box, optimized for performance and SEO, familiar to the team.</p></li><li><p><a href="https://htmx.org/" target="_blank" rel="noreferrer">Htmx</a>: Htmx gives you access to AJAX, CSS Transitions, WebSockets and Server Sent Events directly in HTML, using attributes, so you can build modern user interfaces with the simplicity and power of hypertext htmx is small, dependency-free, extendable &amp; has reduced code base sizes by 67% when compared with react.</p></li></ul><h1 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h1><p>The project will continue with React.js, given the team&#39;s expertise, rich ecosystem, strict project timeline, and its use within HOT. The choice of React.js also allows for separation of concern, without requiring changes to the backend, unlike htmx. Next JS was ruled out because the features it provides are not relavent to the project at this point.</p><p>React.js is licensed under very permissive open-source licenses (MIT) meaning it align with HOT license requirements.</p><h1 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h1><p>Accepted.</p><h1 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h1><p>New developers may need a brief period to adapt to React.js if they are only familiar with other frameworks.</p>',15)]))}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
